// ======================================================================
// 03. イラストの絵（SVG）  (03-data-icons.js)
// 地図の処理は js/01〜36 に分かれていて、番号順に読み込まれる。
// 上から下へ1本につながっており、前のファイルで作った const / function を後ろのファイルが使う。
// ======================================================================
// ---- illustrations: original line drawings, 24x24 box centered at 0,0 ----
// アーチ型の列柱（神殿などの絵）の線を作る。横線2本と、4刻みで並ぶ半円アーチを1本の path 文字列にする
const arches = (() => {
    let d = "M-12,-1 H12 M-12,1.5 H12";
    for (let x = -12; x < 12; x += 4) {
        d += ` M${x},9 V3.5 Q${x + 2},0.6 ${x + 4},3.5 V9`;
    }
    return d;
})();
